define('views/sim-draggable',['require','jquery','underscore','backbone'],function (require) {

    'use strict';

    var $        = require('jquery');
    var _        = require('underscore');
    var Backbone = require('backbone');

    var SimDraggable = Backbone.View.extend({

        initialize: function(options) {

            // Default values
            options = _.extend({
                mouseLeaveCancels: false,
                captureOnBody: true
            }, options);

            this.mouseLeaveCancels = options.mouseLeaveCancels;
            this.captureOnBody = options.captureOnBody;

            if (options.dragFrame)
                this.$dragFrame = $(options.dragFrame);
            else
                throw 'SimDraggable requires an element to be used as a drag frame.';

            this.visible = false;
        },

        bindDragEvents: function() {
            if (this.captureOnBody) {
                $('body')
                    .bind('mousemove touchmove', _.bind(this.drag,    this))
                    .bind('mouseup touchend',    _.bind(this.dragEnd, this));
            }
            else {
                this.$dragFrame
                    .bind('mousemove touchmove', _.bind(this.drag,    this))
                    .bind('mouseup touchend',    _.bind(this.dragEnd, this));

                if (this.mouseLeaveCancels)
                    this.$dragFrame.bind('mouseleave', _.bind(this.dragEnd, this));
            }
        },

        postRender: function() {
            this.resize();
        },

        resize: function(){
            this.updateOnNextFrame = true;

            this.dragOffset = this.$dragFrame.offset();
            this.dragBounds = {
                width:  this.$dragFrame.width(),
                height: this.$dragFrame.height()
            };

            this.width  = this.$el.width();
            this.height = this.$el.height();
        },

        drag: function(event) {},

        dragEnd: function(event) {},

        fixTouchEvents: function(event) {
            if (event.pageX === undefined) {
                event.pageX = event.originalEvent.touches[0].pageX;
                event.pageY = event.originalEvent.touches[0].pageY;
            }
        },

        outOfBounds: function(x, y, dimensions) {
            if (dimensions) {
                return (x + dimensions.width  > this.dragBounds.width  || x < 0 ||
                        y + dimensions.height > this.dragBounds.height || y < 0);
            }
            else {
                return (x > this.dragBounds.width  || x < 0 ||
                        y > this.dragBounds.height || y < 0);
            }
        },

        boxOutOfBounds: function(x, y) {
            return this.outOfBounds(x, y, this);
        },

        show: function() {
            this.$el.show();
            this.visible = true;
        },

        hide: function() {
            this.$el.hide();
            this.visible = false;
        }

    });

    return SimDraggable;
});


define('text!templates/moving-man.html',[],function () { return '<div class="image"></div>\r\n<div class="arrow velocity">\r\n    <div class="arrow-head"></div>\r\n    <div class="arrow-shaft"></div>\r\n</div>\r\n<div class="arrow acceleration">\r\n    <div class="arrow-head"></div>\r\n    <div class="arrow-shaft"></div>\r\n</div>';});


define('views/moving-man',['require','exports','module','underscore','buzz','views/sim-draggable','text!templates/moving-man.html','css!styles/moving-man'],function (require, exports, module) {

    'use strict';

    // var $ = require('jquery');
    var _    = require('underscore');
    var buzz = require('buzz');

    var SimDraggable = require('views/sim-draggable');

    var html = require('text!templates/moving-man.html');

    require('css!styles/moving-man');

    /**
     * Constants
     */
    var MOVEMENT_STATE_IDLE  = 0;
    var MOVEMENT_STATE_LEFT  = 1;
    var MOVEMENT_STATE_RIGHT = 2;

    // These are from PhET and seem fairly arbitrary...
    var VELOCITY_SCALE     = 0.2;
    var ACCELERATION_SCALE = 0.8;

    /**
     * The moving man view is the focus of the application.  He
     *   represents the state of the moving man model and animates
     *   with changes to the model.  The user can also drag him,
     *   changing his position and derivative variables in turn.
     */
    var MovingManView = SimDraggable.extend({

        template: _.template(html),

        tagName: 'div',
        className: 'moving-man-view',

        events: {
            'mousedown'  : 'down',
            'touchstart' : 'down'
        },

        initialize: function(options) {
            SimDraggable.prototype.initialize.apply(this, [options]);

            this.simulation = options.simulation;
            this.movingMan  = this.simulation.movingMan;

            this.velocityVectorEnabled = false;
            this.velocityVectorVisible = false;

            this.accelerationVectorEnabled = false;
            this.accelerationVectorVisible = false;

            var formats = ['ogg', 'mp3', 'wav'];

            this.crashSound = new buzz.sound('audio/thud', { formats: formats });

            this.gruntSounds = [
                new buzz.sound('audio/grunt01', { formats: formats }),
                new buzz.sound('audio/grunt02', { formats: formats }),
                new buzz.sound('audio/grunt03', { formats: formats }),
                new buzz.sound('audio/grunt04', { formats: formats })
            ];

            this.gruntSoundGroup = new buzz.group(this.gruntSounds);

            this.lowVolume();

            this.listenTo(this.movingMan, 'collide', this.collide);
        },

        render: function() {
            this.renderMovingMan();
            this.bindDragEvents();
            this.resize();
            this.update(0, 0);
        },

        renderMovingMan: function() {
            this.$el.html(this.template());

            this.$velocityVector     = this.$('.arrow.velocity');
            this.$accelerationVector = this.$('.arrow.acceleration');
        },

        resize: function() {
            SimDraggable.prototype.resize.apply(this);

            this.pixelRatio = this.dragBounds.width / this.simulation.get('containerWidth');
        },

        down: function(event) {
            event.preventDefault();

            this.dragging = true;
            this.$el.addClass('dragging');

            // Start recording on drag if the simulation records and isn't currently
            if (!this.simulation.noRecording && !this.simulation.get('recording'))
                this.simulation.record();
            if (this.simulation.get('paused'))
                this.simulation.play();

            this.fixTouchEvents(event);

            this.dragX = event.pageX;
        },

        drag: function(event) {
            if (this.dragging) {

                this.fixTouchEvents(event);

                // Get position
                this._xPercent = (event.pageX - this.dragOffset.left) / this.dragBounds.width;
                this._xPosition = (this._xPercent * this.simulation.get('containerWidth')) - this.simulation.get('halfContainerWidth');

                this.movingMan.setMousePosition(this._xPosition);
                this.movingMan.positionDriven(true);

                // Get direction
                if ((event.pageX - this.dragX) > 0)
                    this.movementState = MOVEMENT_STATE_RIGHT;
                else if ((event.pageX - this.dragX) < 0)
                    this.movementState = MOVEMENT_STATE_LEFT;
                this.dragX = event.pageX;
            }
        },

        dragEnd: function(event) {
            if (this.dragging) {
                this.dragging = false;
                this.$el.removeClass('dragging');

                this.movementState = MOVEMENT_STATE_IDLE;
            }
        },

        update: function(time, delta) {
            this._lastPosition = this._position;
            this._position = this.movingMan.get('position');

            this._lastVelocity = this._velocity;
            this._velocity = this.movingMan.get('velocity');

            this._lastAcceleration = this._acceleration;
            this._acceleration = this.movingMan.get('acceleration');

            if (!this.updateOnNextFrame &&
                this._position === this._lastPosition &&
                this._velocity === this._lastVelocity &&
                this._acceleration === this._lastAcceleration)
                return;

            if (this.updateOnNextFrame)
                this.updateOnNextFrame = false;

            this._updatePosition();

            this._updateDirection();

            this._updateArrows();
        },

        _updatePosition: function() {
            // Update position
            this._xPercent  = (this._position + this.simulation.get('halfContainerWidth')) / this.simulation.get('containerWidth');
            this._xPixels   = this._xPercent * this.dragBounds.width;
            this._translate = 'translateX(' + this._xPixels + 'px)';

            this.$el.css({
                '-webkit-transform': this._translate,
                '-ms-transform':     this._translate,
                '-o-transform':      this._translate,
                'transform':         this._translate,
            });
        },

        _updateDirection: function() {
            if (this.movingMan.get('velocity') > 0.1)
                this.movementState = MOVEMENT_STATE_RIGHT;
            else if (this.movingMan.get('velocity') < -0.1)
                this.movementState = MOVEMENT_STATE_LEFT;
            else
                this.movementState = MOVEMENT_STATE_IDLE;

            // Update direction
            if (this.visibleMovementState !== this.movementState) {
                this.visibleMovementState = this.movementState;

                switch (this.movementState) {
                    case MOVEMENT_STATE_IDLE:
                        this.$el
                            .removeClass('left')
                            .removeClass('right');
                        break;
                    case MOVEMENT_STATE_RIGHT:
                        this.$el
                            .removeClass('left')
                            .addClass('right');
                        break;
                    case MOVEMENT_STATE_LEFT:
                        this.$el
                            .removeClass('right')
                            .addClass('left');
                        break;
                }
            }
        },

        _updateArrows: function() {
            // Update arrow visiblity
            if (this.velocityVectorEnabled !== this.velocityVectorVisible) {
                if (this.velocityVectorEnabled) {
                    this.$velocityVector.show();
                    this.velocityVectorVisible = true;
                }
                else {
                    this.$velocityVector.hide();
                    this.velocityVectorVisible = false;
                }
            }

            if (this.accelerationVectorEnabled !== this.accelerationVectorVisible) {
                if (this.accelerationVectorEnabled) {
                    this.$accelerationVector.show();
                    this.accelerationVectorVisible = true;
                }
                else {
                    this.$accelerationVector.hide();
                    this.accelerationVectorVisible = false;
                }
            }

            // Update arrow lengths and directions
            var vectorWidth;

            if (this.velocityVectorVisible) {
                vectorWidth = Math.abs(this._velocity * VELOCITY_SCALE) * this.pixelRatio;
                this.$velocityVector.width(vectorWidth);

                if (this._velocity > 0) {
                    this.$velocityVector
                        .removeClass('left')
                        .addClass('right');
                }
                else {
                    this.$velocityVector
                        .removeClass('right')
                        .addClass('left');
                }
            }

            if (this.accelerationVectorVisible) {
                vectorWidth = Math.abs(this._acceleration * ACCELERATION_SCALE) * this.pixelRatio;
                this.$accelerationVector.width(vectorWidth);

                if (this._acceleration > 0) {
                    this.$accelerationVector
                        .removeClass('left')
                        .addClass('right');
                }
                else {
                    this.$accelerationVector
                        .removeClass('right')
                        .addClass('left');
                }
            }
        },

        showVelocityVector: function() {
            this.velocityVectorEnabled = true;
            this.updateOnNextFrame = true;
        },

        hideVelocityVector: function() {
            this.velocityVectorEnabled = false;
            this.updateOnNextFrame = true;
        },

        showAccelerationVector: function() {
            this.accelerationVectorEnabled = true;
            this.updateOnNextFrame = true;
        },

        hideAccelerationVector: function() {
            this.accelerationVectorEnabled = false;
            this.updateOnNextFrame = true;
        },

        muteVolume: function() {
            this.crashSound.setVolume(0);
            this.gruntSoundGroup.setVolume(0);
        },

        lowVolume: function() {
            this.crashSound.setVolume(20);
            this.gruntSoundGroup.setVolume(20);
        },

        highVolume: function() {
            this.crashSound.setVolume(80);
            this.gruntSoundGroup.setVolume(80);
        },

        collide: function() {
            // Stop previous sounds
            this.crashSound.stop();
            this.gruntSoundGroup.stop();

            this.crashSound.play();
            _.sample(this.gruntSounds).play();
        }

    });

    return MovingManView;
});



define('text!templates/scene.html',[],function () { return '<div class="scene">\r\n    <div class="clouds">\r\n        <div class="cloud cloud-1"></div>\r\n        <!-- Time for multiple clouds to dance around -->\r\n        <div class="cloud cloud-2"></div>\r\n        <div class="cloud cloud-3"></div>\r\n        <div class="cloud cloud-4"></div>\r\n        <div class="cloud cloud-5"></div>\r\n    </div>\r\n\r\n    <div class="clock">\r\n        <span class="time">0.0</span> \r\n        <span class="units">sec</span>\r\n    </div>\r\n    \r\n    <div class="tree"></div>\r\n    <div class="house"></div>\r\n\r\n    <div class="man-container"></div>\r\n\r\n    <div class="walls-container">\r\n        <div class="wall wall-left">\r\n            <button class="btn wall-hide" title="Hide Walls"><span class="fa fa-caret-square-o-down"></span></button>\r\n            <button class="btn wall-show" title="Show Walls"><span class="fa fa-caret-square-o-up"></span></button>\r\n        </div>\r\n        <div class="wall wall-right">\r\n            <button class="btn wall-hide" title="Hide Walls"><span class="fa fa-caret-square-o-down"></span></button>\r\n            <button class="btn wall-show" title="Show Walls"><span class="fa fa-caret-square-o-up"></span></button>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class="ruler">\r\n    <% for (var i = -10; i <= 10; i++) { %>\r\n    <div class="ruler-number"><%= i % 2 ? \'&nbsp;\' : i %></div>\r\n    <% } %>\r\n    <div class="ruler-label">meters</div>\r\n</div>';});

define('views/scene',['require','jquery','underscore','backbone','views/moving-man','css!styles/scene','text!templates/scene.html'],function(require) {

    'use strict';

    var $        = require('jquery');
    var _        = require('underscore');
    var Backbone = require('backbone');

    var MovingManView = require('views/moving-man');

    // CSS
    require('css!styles/scene');

    // HTML
    var template = require('text!templates/scene.html');

    /**
     * The SceneView renders all the scene objects, including
     *   the MovingManView.
     */
    var SceneView = Backbone.View.extend({

        template: _.template(template),
        tagName: 'div',
        className: 'scene-view',

        events: {
            'click .wall-hide' : 'hideWalls',
            'click .wall-show' : 'showWalls',

            // Just an Easter Egg
            'click .cloud' : 'cloudClicked'
        },

        initialize: function(options) {

            // Default values
            options = _.extend({
                compact: false
            }, options);

            this.compact = options.compact;

            // Save options
            if (options.simulation)
                this.simulation = options.simulation;
            else
                throw 'SceneView requires a simulation model to render.';

            // Bind DOM events
            $(window).bind('resize', $.proxy(this.windowResized, this));

            // Listen to simulation events
            this.listenTo(this.simulation, 'change:wallsEnabled', this.wallsEnabledChanged);
            this.listenTo(this.simulation, 'change:time',         this.timeChanged);
        },

        /**
         * Renders content and canvas for heatmap
         */
        render: function() {
            this.$el.html(this.template());

            if (this.compact)
                this.$el.addClass('compact');

            this.$walls = this.$('.wall');
            this.$time  = this.$('.clock > .time');

            this.renderMovingManView();

            return this;
        },

        /**
         * Renders html container
         */
        renderMovingManView: function() {
            var $manContainer = this.$('.man-container');
            this.movingManView = new MovingManView({
                simulation: this.simulation,
                dragFrame: $manContainer[0]
            });
            this.movingManView.render();
            $manContainer.html(this.movingManView.el);
        },

        /**
         * Called after every component on the page has rendered to make sure
         *   things like widths and heights and offsets are correct.
         */
        postRender: function() {
            this.movingManView.postRender();
        },

        /**
         * Responds to resize events.
         */
        resize: function() {},

        /**
         * Called on a window resize to resize the canvas
         */
        windowResized: function(event) {
            this.resizeOnNextUpdate = true;
        },

        /**
         * Responds to resize events and draws everything.
         */
        update: function(time, delta) {
            if (this.resizeOnNextUpdate)
                this.resize();

            this.movingManView.update(time, delta);
        },

        /**
         * Hides the walls and updates the sim
         */
        hideWalls: function() {
            this.simulation.set('wallsEnabled', false);
        },

        /**
         * Hides the walls and updates the sim
         */
        showWalls: function() {
            this.simulation.set('wallsEnabled', true);
        },

        /**
         * Updates the visual state of the walls when the simulation
         *   changes.
         */
        wallsEnabledChanged: function(model, wallsEnabled, options) {
            if (wallsEnabled)
                this.$walls.removeClass('disabled');
            else
                this.$walls.addClass('disabled');
        },

        /**
         * Updates the time counter when it changes in the sim.
         */
        timeChanged: function(model, time, options) {
            this.$time.text(time.toFixed(1));
        },

        /**
         * Just a little Easter Egg to start the cloud animation.
         *   The user has to click each cloud to activate it.
         */
        cloudClicked: function(event) {
            if (!this.cloudsClicked)
                this.cloudsClicked = {};

            this.cloudsClicked[$(event.target).attr('class')] = true;

            if (_.size(this.cloudsClicked) >= 5)
                this.$('.clouds').addClass('moving');
        }
    });

    return SceneView;
});

