define('text!templates/sim.html',[],function () { return '\r\n<div class="content-area">\r\n    <span class="scene-view-placeholder"></span>\r\n    <div class="sim-controls">\r\n        <div class="position-row variable-row">\r\n            <div class="row-content"></div>\r\n            <div class="hidden-title" title="Click to show">(Position Hidden)</div>\r\n            <button class="btn row-hide" title="Click to hide"><span class="fa fa-toggle-up"></span></button>\r\n            <button class="btn row-show" title="Click to show"><span class="fa fa-toggle-down"></span></button>\r\n        </div>\r\n        <div class="velocity-row variable-row">\r\n            <div class="row-content"></div>\r\n            <div class="hidden-title" title="Click to show">(Velocity Hidden)</div>\r\n            <button class="btn row-hide" title="Click to hide"><span class="fa fa-toggle-up"></span></button>\r\n            <button class="btn row-show" title="Click to show"><span class="fa fa-toggle-down"></span></button>\r\n        </div>\r\n        <div class="acceleration-row variable-row">\r\n            <div class="row-content"></div>\r\n            <div class="hidden-title" title="Click to show">(Acceleration Hidden)</div>\r\n            <button class="btn row-hide" title="Click to hide"><span class="fa fa-toggle-up"></span></button>\r\n            <button class="btn row-show" title="Click to show"><span class="fa fa-toggle-down"></span></button>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<span class="playback-controls-placeholder"></span>\r\n';});


define('text!templates/variable-control.html',[],function () { return '<div class="variable-controls <%= className %>">\r\n    <div class="left-wrapper">\r\n        <div class="label-row">\r\n            <div class="label-wrapper">\r\n                <label class="name"><%= name %> <span class="driving-icon fa fa-compass"></span></label>\r\n            </div>\r\n            <div class="value-wrapper">\r\n                <div class="input-group value-group">\r\n                    <input type="text" class="form-control variable-text" value="0.00" />\r\n                    <span class="input-group-addon"><%= units %></span>\r\n                </div>\r\n                <% if (expression) { %>\r\n                    <div class="input-group expression-group">\r\n                        <input type="text" class="form-control expression-text" value="7 * sin(t) + 2" />\r\n                        <span class="input-group-addon"><%= units %></span>\r\n                    </div>\r\n                    <button class="btn expression-help" title="Help with Expressions" data-toggle="modal" data-target="#<%= help_modal_id %>"><span class="fa fa-question-circle"></span></button>\r\n                <% } %>\r\n            </div>\r\n        </div>\r\n        <% if (vectors) { %>\r\n        <div class="vector-check-wrapper">\r\n            <input type="checkbox" id="vector-check-<%= unique %>" class="vector-check">\r\n            <label for="vector-check-<%= unique %>">Show Vector</label>\r\n        </div>\r\n        <% } %>\r\n        <% if (expression) { %>\r\n        <button class="btn btn-expression from-expression"><span class="function-icon">&fnof;</span> Use Function</button>\r\n        <button class="btn btn-expression drop-expression"><span class="fa fa-close"></span> Drop Function</button>\r\n        <% } %>\r\n    </div>\r\n    <div class="variable-slider slider"></div>\r\n<div>';});


define('text!templates/function-help-modal.html',[],function () { return '<div class="modal" id="<%= help_modal_id %>">\r\n    <div class="modal-dialog">\r\n        <div class="modal-content">\r\n            <div class="modal-header">\r\n                <button type="button" class="close" data-dismiss="modal"><span aria-hidden="true">&times;</span><span class="sr-only">Close</span></button>\r\n                <h4 class="modal-title">About Custom Functions</h4>\r\n            </div>\r\n            <div class="modal-body">\r\n                <p>You can specify an expression where <em>position</em> is a function of <em>time</em> (<code>t</code>).</p>\r\n                <br>\r\n                <h4>Examples of valid expressions:</h4>\r\n                <ul>\r\n                    <li><span class="implicit-expression">&fnof;(t) = </span><code>3 * t + 2</code></li>\r\n                    <li><span class="implicit-expression">&fnof;(t) = </span><code>2*sin(t)</code></li>\r\n                    <li><span class="implicit-expression">&fnof;(t) = </span><code>pow(t,2)</code></li>\r\n                    <li><span class="implicit-expression">&fnof;(t) = </span><code>7*pow(sin(t),2)</code></li>\r\n                    <li><span class="implicit-expression">&fnof;(t) = </span><code>sqrt(t * 4)</code></li>\r\n                </ul>\r\n                <p>\r\n                    Note that you only input the right side of the equation and also that multiplication must be specified explicitly as in <code>3 * t</code>, instead of implicitly as in <code>3t</code>.\r\n                </p>\r\n                <br>\r\n                <h4>\r\n                    Available math functions:\r\n                </h4>\r\n                <table class="table functions-table">\r\n                    <thead>\r\n                        <th>Function</th>\r\n                        <th>Description</th>\r\n                    </thead>\r\n                    <tbody>\r\n                        <tr>\r\n                            <td>abs(x)</td>\r\n                            <td>absolute value of x</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>acos(x)</td>\r\n                            <td>arccosine of x</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>asin(x)</td>\r\n                            <td>arcsine of x</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>atan(x)</td>\r\n                            <td>arctangent of x</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>cos(x)</td>\r\n                            <td>cosine of x</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>exp(x)</td>\r\n                            <td>E<sup>x</sup>, where E is Euler\'s constant</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>log(x)</td>\r\n                            <td>natural logarithm of x</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>pow(x, y)</td>\r\n                            <td>x<sup>y</sup></td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>sin(x)</td>\r\n                            <td>sine of x</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>sqrt(x)</td>\r\n                            <td>square root of x</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>tan(x)</td>\r\n                            <td>tangent of x</td>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n                <br>\r\n                <h4>\r\n                    Available math constants:\r\n                </h4>\r\n                <table class="table functions-table">\r\n                    <thead>\r\n                        <th>Constant</th>\r\n                        <th>Description</th>\r\n                    </thead>\r\n                    <tbody>\r\n                        <tr>\r\n                            <td>PI</td>\r\n                            <td>Math constant <em>&pi;</em> and ratio of circumference of a circle to its diameter</td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>E</td>\r\n                            <td>Euler\'s constant and the base of natural logarithms</td>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n            </div>\r\n            <div class="modal-footer">\r\n                <button type="button" class="btn btn-default" data-dismiss="modal">Close</button>\r\n            </div>\r\n        </div><!-- /.modal-content -->\r\n    </div><!-- /.modal-dialog -->\r\n</div><!-- /.modal -->';});

define('views/sim',['require','jquery','underscore','common/app/sim','models/moving-man-simulation','views/scene','nouislider','bootstrap','css!styles/sim','css!styles/variable-controls','css!common/styles/slider','css!common/styles/radio','text!templates/sim.html','text!templates/variable-control.html','text!templates/function-help-modal.html'],function (require) {

    'use strict';

    var $                   = require('jquery');
    var _                   = require('underscore');

    var SimView             = require('common/app/sim');
    var MovingManSimulation = require('models/moving-man-simulation');
    var SceneView           = require('views/scene');

    require('nouislider');
    require('bootstrap');

    // CSS
    require('css!styles/sim');
    require('css!styles/variable-controls');
    require('css!common/styles/slider');
    require('css!common/styles/radio');

    // HTML
    var simHtml             = require('text!templates/sim.html');
    var variableControlHtml = require('text!templates/variable-control.html');
    var functionHelpHtml    = require('text!templates/function-help-modal.html');

    /**
     * This is the umbrella view for everything in a simulation tab.
     *   It will be extended by both the Intro module and the Charts
     *   and contains all the common functionality between the two.
     */
    var MovingManSimView = SimView.extend({

        /**
         * Root element properties
         */
        tagName:   'section',
        className: 'sim-view',

        /**
         * Template for rendering the basic scaffolding
         */
        template: _.template(simHtml),
        variableControlTemplate: _.template(variableControlHtml),
        functionHelpTemplate: _.template(functionHelpHtml),

        /**
         * Dom event listeners
         */
        events: {
            // Playback controls
            'click .play-btn'   : 'play',
            'click .pause-btn'  : 'pause',
            'click .reset-btn'  : 'reset',

            'click .from-expression' : 'useExpression',
            'click .drop-expression' : 'dropExpression',

            'slide .position .slider'     : 'changePosition',
            'slide .velocity .slider'     : 'changeVelocity',
            'slide .acceleration .slider' : 'changeAcceleration',

            'keyup .position .variable-text'     : 'changePosition',
            'keyup .velocity .variable-text'     : 'changeVelocity',
            'keyup .acceleration .variable-text' : 'changeAcceleration',

            'change .velocity     .vector-check' : 'changeVelocityVectorVisibility',
            'change .acceleration .vector-check' : 'changeAccelerationVectorVisibility',

            'keyup .position .expression-text' : 'changeExpression'
        },

        /**
         * Inits simulation, views, and variables.
         *
         * @params options
         */
        initialize: function(options) {
            options = _.extend({
                link: 'moving-man',
            }, options);

            SimView.prototype.initialize.apply(this, [options]);

            // Initialize the HeatmapView
            this.initSceneView();

            this.listenTo(this.simulation.movingMan, 'change:position',     this.positionChanged);
            this.listenTo(this.simulation.movingMan, 'change:velocity',     this.velocityChanged);
            this.listenTo(this.simulation.movingMan, 'change:acceleration', this.accelerationChanged);

            this.listenTo(this.simulation.movingMan, 'change:motionStrategy', this.motionStrategyChanged);
        },

        /**
         * Initializes the Simulation.
         */
        initSimulation: function() {
            this.simulation = new MovingManSimulation();
        },

        /**
         * Initializes the SceneView.
         */
        initSceneView: function() {
            this.sceneView = new SceneView({
                simulation: this.simulation
            });
        },

        /**
         * Renders everything
         */
        render: function() {
            this.$el.empty();

            this.renderScaffolding();
            this.renderSceneView();
            this.renderVariableControls();

            this.simulation.movingMan.trigger('change:motionStrategy', this.simulation.movingMan);

            return this;
        },

        /**
         * Renders page content. Should be overriden by child classes
         */
        renderScaffolding: function() {
            this.$el.html(this.template());
        },

        /**
         * Renders the scene view
         */
        renderSceneView: function() {
            this.sceneView.render();
            this.$('.scene-view-placeholder').replaceWith(this.sceneView.el);
        },

        /**
         * Renders all the variable controls and initializes the
         *   special inputs like the sliders.
         */
        renderVariableControls: function() {
            var $position = $(this.variableControlTemplate(this.getPositionTemplateData()));
            var $velocity = $(this.variableControlTemplate(this.getVelocityTemplateData()));
            var $acceleration = $(this.variableControlTemplate(this.getAccelerationTemplateData()));

            this.$variables = $()
                .add($position)
                .add($velocity)
                .add($acceleration);

            this.$('.position-row .row-content').append($position);
            this.$('.velocity-row .row-content').append($velocity);
            this.$('.acceleration-row .row-content').append($acceleration);

            this.$position     = $position;
            this.$velocity     = $velocity;
            this.$acceleration = $acceleration;

            this.initVariableSliders();

            this.$positionInputs     = this.$position.find(    '.variable-text, .slider');
            this.$velocityInputs     = this.$velocity.find(    '.variable-text, .slider');
            this.$accelerationInputs = this.$acceleration.find('.variable-text, .slider');

            this.$expression      = this.$('.position .expression-text');
            this.$expressionGroup = this.$('.position .expression-group');

            this.$el.append(this.functionHelpTemplate({
                help_modal_id: this.getHelpModalId()
            }));
        },

        /**
         * Intializes all the variable sliders and links their values to
         *   the corresponding text boxes.
         */
        initVariableSliders: function() {
            var sliderOptions = this.getSliderOptions();

            this.$variables.each(function(){
                var $slider = $(this).find('.variable-slider');
                $slider.noUiSlider(sliderOptions);
                $slider.Link('lower').to($(this).find('.variable-text'));
            });
        },

        /**
         * Default intro view needs horizontal sliders, while the charts
         *   view has more compact variable controls with a vertical slider.
         */
        getSliderOptions: function() {
            return {
                start: 0,
                range: {
                    min: -10,
                    max:  10
                }
            };
        },

        /**
         * Returns the id of the help modal element.
         */
        getHelpModalId: function() {
            return this.name + '-function-help-modal';
        },

        /**
         * Returns the template data for the position section.
         */
        getPositionTemplateData: function() {
            return {
                className: 'position',
                name:  'Position',
                units: 'm',
                unique: this.name + '-position',
                vectors: false,
                expression: true,
                help_modal_id: this.getHelpModalId()
            };
        },

        /**
         * Returns the template data for the velocity section.
         */
        getVelocityTemplateData: function() {
            return {
                className: 'velocity',
                name:  'Velocity',
                units: 'm/s',
                unique: this.name + '-velocity',
                vectors: true,
                expression: false
            };
        },

        /**
         * Returns the template data for the acceleration section.
         */
        getAccelerationTemplateData: function() {
            return {
                className: 'acceleration',
                name:  'Acceleration',
                units: 'm/s<sup>2</sup>',
                unique: this.name + '-acceleration',
                vectors: true,
                expression: false
            };
        },

        /**
         * Called after every component on the page has rendered to make sure
         *   things like widths and heights and offsets are correct.
         */
        postRender: function() {
            this.sceneView.postRender();
        },

        /**
         * Resets all the components of the view.
         */
        resetComponents: function() {
            SimView.prototype.resetComponents.apply(this);
            this.initSceneView();
        },

        /**
         * This is run every tick of the updater.  It updates the wave
         *   simulation and the views.
         */
        update: function(time, delta) {
            // Update the model
            this.simulation.update(time, delta);

            // Update the scene
            this.sceneView.update(time, delta);
        },

        /**
         * Switches positon to expression mode and updates simulation.
         */
        useExpression: function() {
            this.$('.position').addClass('expression');

            /*
             * PhET didn't do this, but I'm disabling the position
             *   while using an expression because it can cause
             *   unexpected behavior and is otherwise useless.
             */
            this.$('.position .slider').attr('disabled', 'disabled');

            this.changeExpression();
        },

        /**
         * Switches position away from expression mode and updates sim.
         */
        dropExpression: function() {
            this.$('.position').removeClass('expression');

            this.$('.position .slider').removeAttr('disabled');

            // Update simulation
            this.simulation.dropCustomPositionFunction();
        },

        /**
         * Tries to set the custom position function on the simulation and
         *   shows error feedback to the user if it fails.
         */
        changeExpression: function(event) {
            try {
                this.simulation.useCustomPositionFunction(this.$expression.val());
                if (this.simulation.noRecording) {
                    /* Start back at time zero so the user can see what
                     *  his or her function does. If it's a simulation
                     *  that records (i.e., Charts), the user will have
                     *  control over the time, so this isn't needed.
                     */
                    this.simulation.resetTimeAndHistory();
                }
                this.$expressionGroup.removeClass('error');
            }
            catch (e) {
                this.$expressionGroup.addClass('error');
            }
        },

        /**
         * Changes the position in the simulation according to input.
         */
        changePosition: function(event) {
            var position = parseFloat($(event.target).val());
            if (!isNaN(position)) {
                this.inputLock(function(){
                    this.simulation.movingMan.positionDriven(true);
                    this.simulation.movingMan.setMousePosition(position);
                });
            }
        },

        /**
         * Changes the velocity in the simulation according to input.
         */
        changeVelocity: function(event) {
            var velocity = parseFloat($(event.target).val());
            if (!isNaN(velocity)) {
                this.inputLock(function(){
                    this.simulation.movingMan.velocityDriven(true);
                    this.simulation.movingMan.set('velocity', velocity);
                });
            }
        },

        /**
         * Changes the acceleration in the simulation according to input.
         */
        changeAcceleration: function(event) {
            var acceleration = parseFloat($(event.target).val());
            if (!isNaN(acceleration)) {
                this.inputLock(function(){
                    this.simulation.movingMan.accelerationDriven(true);
                    this.simulation.movingMan.set('acceleration', acceleration);
                });
            }
        },

        /**
         * Changes the position inputs according to the simulation value.
         */
        positionChanged: function(model, value) {
            if (!this.simulation.movingMan.positionDriven() || this.sceneView.movingManView.dragging || this.simulation.playingBack()) {
                this.updateLock(function(){
                    this.$positionInputs.val(value.toFixed(2));
                });
            }
        },

        /**
         * Changes the velocity inputs according to the simulation value.
         */
        velocityChanged: function(model, value) {
            this.updateLock(function(){
                this.$velocityInputs.val(value.toFixed(2));
            });
        },

        /**
         * Changes the acceleration inputs according to the simulation value.
         */
        accelerationChanged: function(model, value) {
            this.updateLock(function(){
                this.$accelerationInputs.val(value.toFixed(2));
            });
        },

        /**
         * Changes the visibility of the velocity vector on the moving man.
         */
        changeVelocityVectorVisibility: function(event) {
            if ($(event.target).is(':checked'))
                this.sceneView.movingManView.showVelocityVector();
            else
                this.sceneView.movingManView.hideVelocityVector();
        },

        /**
         * Changes the visibility of the acceleration vector on the moving man.
         */
        changeAccelerationVectorVisibility: function(event) {
            if ($(event.target).is(':checked'))
                this.sceneView.movingManView.showAccelerationVector();
            else
                this.sceneView.movingManView.hideAccelerationVector();
        },

        /**
         * The simulation's moving man changed its motion strategy.
         */
        motionStrategyChanged: function(model, value, options) {
            var $variable;

            if (model.positionDriven())
                $variable = this.$position;
            else if (model.velocityDriven())
                $variable = this.$velocity;
            else if (model.accelerationDriven())
                $variable = this.$acceleration;

            this.$variables.removeClass('driving');

            $variable.addClass('driving');
        },

        /**
         * The simulation changed its paused state.
         */
        pausedChanged: function() {
            if (this.simulation.get('paused'))
                this.$el.removeClass('playing');
            else
                this.$el.addClass('playing');
        },

    });

    return MovingManSimView;
});


define('text!templates/intro-controls.html',[],function () { return '<div class="playback-controls-wrapper intro-controls-wrapper">\r\n    <button class="playback-btn play-btn"   title="Resume"><span class="fa fa-play"></span></button>\r\n    <button class="playback-btn pause-btn"  title="Pause"><span class="fa fa-pause"></span></button>\r\n    \r\n    <button class="btn btn-normal reset-btn" title="Reset All">Reset All</button>\r\n</div>';});


define('views/sim/intro',['require','underscore','models/moving-man-simulation','views/sim','text!templates/intro-controls.html','css!styles/playback-controls'],function(require) {

    'use strict';

    var _ = require('underscore');

    var MovingManSimulation = require('models/moving-man-simulation');
    var MovingManSimView    = require('views/sim');

    // HTML
    var playbackControlsHtml = require('text!templates/intro-controls.html');

    // CSS
    require('css!styles/playback-controls');

    /**
     * Extends the functionality of the MovingManSimView to create
     *   the Intro tab. This one is a very simple view, so not much
     *   additional functionality is needed.
     */
    var IntroSimView = MovingManSimView.extend({

        events: _.extend(MovingManSimView.prototype.events, {

        }),

        initialize: function(options) {
            options = _.extend({
                title: 'Introduction',
                name:  'intro'
            }, options);

            MovingManSimView.prototype.initialize.apply(this, [ options ]);

            this.listenTo(this.simulation, 'change:paused', this.pausedChanged);
        },

        /**
         * Initializes the Simulation.
         */
        initSimulation: function() {
            this.simulation = new MovingManSimulation({
                paused: true
            }, {
                noRecording: true
            });
        },

        /**
         * Renders everything
         */
        render: function() {
            MovingManSimView.prototype.render.apply(this);

            this.renderPlaybackControls();

            this.simulation.trigger('change:paused');

            return this;
        },

        /**
         * Renders the playback controls
         */
        renderPlaybackControls: function() {
            this.$('.playback-controls-placeholder').replaceWith(playbackControlsHtml);
        }

    });

    return IntroSimView;
});


define('text!common/graph/graph.html',[],function () { return '<div class="graph-view-graph-wrapper">\r\n    <figcaption class="graph-title"><%= title %></figcaption>\r\n\r\n    <div class="graph-canvas-wrapper">\r\n        <canvas class="graph-canvas"></canvas>\r\n    </div>\r\n\r\n    <% if (y) { %>\r\n    <div class="graph-y">\r\n        <label class="graph-axis-label"><%= y.label %></label>\r\n        <div class="graph-y-numbers">\r\n        <% var height = 100.0 / Math.ceil((y.end - y.start) / y.step); %>\r\n        <% for (var j = y.end; j >= y.start - 0.001; j -= y.step) { %>\r\n            <div class="graph-number" style="height: <%= height %>%"><span><%= y.showNumbers ? j.toFixed(y.decimalPlaces) : \'\' %></span></div>\r\n        <% } %>\r\n        </div>\r\n    </div>\r\n    <% } %>\r\n\r\n    <% if (x) { %>\r\n    <div class="graph-x">\r\n        <label class="graph-axis-label"><%= x.label %></label>\r\n        <div class="graph-x-numbers">\r\n        <% var width = 100.0 / Math.ceil((x.end - x.start) / x.step); %>\r\n        <% for (var i = x.start; i <= x.end + 0.001; i += x.step) { %>\r\n            <div class="graph-number" style="width: <%= width %>%"><span><%= x.showNumbers ? i.toFixed(x.decimalPlaces) : \'\' %></span></div>\r\n        <% } %>\r\n        </div>\r\n    </div>\r\n    <% } %>\r\n</div>';});


define('common/graph/graph',['require','jquery','underscore','backbone','text!./graph.html','less!./graph'],function(require) {

    'use strict';

    var $        = require('jquery');
    var _        = require('underscore');
    var Backbone = require('backbone');

    var html = require('text!./graph.html');

    require('less!./graph');

    /**
     * GraphView is not intended to be directly instantiated but extended
     *   for specific purposes.  Functions that must be filled by child
     *   prototypes before the GraphView is useful:
     *
     *     + renderContainer
     *     + initPoints
     *     + calculatePoints
     */
    var GraphView = Backbone.View.extend({

        template: _.template(html),

        tagName: 'figure',
        className: 'graph-view',

        initialize: function(options) {

            // Default values
            options = _.extend({
                title: 'Value',
                x: {
                    start: 0,
                    end: 100,
                    step: 10,
                    label: 'x',
                    decimalPlaces: 0,
                    showNumbers: true
                },
                y: {
                    start: 0,
                    end: 100,
                    step: 10,
                    label: 'y',
                    decimalPlaces: 0,
                    showNumbers: true
                },
                lineThickness: 5,
                lineColor: '#000',
                gridColor: '#ddd',
                latitudinalGridLines: 3,
                longitudinalGridLines: 9
            }, options);

            // Save graph information for rendering
            this.graphInfo = {
                title: options.title,
                x: options.x,
                y: options.y
            };

            this.latitudinalGridLines  = options.latitudinalGridLines;
            this.longitudinalGridLines = options.longitudinalGridLines;

            this.lineThickness = options.lineThickness;
            this.lineColor = options.lineColor;
            this.gridColor = options.gridColor;

            this.graphVisible = true;

            // Bind events
            $(window).bind('resize', $.proxy(this.windowResized, this));

            this.initPoints();
        },

        /**
         * Renders content and canvas for heatmap
         */
        render: function() {
            this.$el.empty();

            this.renderContainer();
            this.initCanvas();
            this.initPoints();

            return this;
        },

        /**
         * Renders html container
         */
        renderContainer: function() {},

        /**
         * Called after every component on the page has rendered to make sure
         *   things like widths and heights and offsets are correct.
         */
        postRender: function() {
            this.resize();
        },

        /**
         * Saves references to the canvas element and its context
         */
        initCanvas: function() {
            this.$canvas = this.$('canvas');
            this.$canvasWrapper = this.$canvas.parent();

            this.context = this.$canvas[0].getContext('2d');
        },

        /**
         * Called on a window resize to resize the canvas
         */
        windowResized: function(event) {
            this.resizeOnNextUpdate = true;
        },

        /**
         * Does the actual resizing of the canvas
         */
        resize: function(event) {
            var width  = this.$canvas.parent().innerWidth();
            var height = this.$canvas.parent().innerHeight() || 200;
            this.width  = width;
            this.height = height;
            this.$canvas.width(width);
            this.$canvas.height(height);
            this.$canvas[0].width = width;
            this.$canvas[0].height = height;
            this.resizeOnNextUpdate = false;
        },

        /**
         * Initializes points array and sets default points.
         */
        initPoints: function() {
            this.points = [];
        },

        /**
         * Calculates point data before drawing.
         */
        calculatePoints: function(time, delta) {},

        /**
         * Draws a blank graph with lines.
         */
        drawGraph: function() {
            var context = this.context;

            // Draw background
            context.fillStyle = '#fff';
            context.fillRect(0, 0, this.width, this.height);

            // Draw Grid
            context.beginPath();

            var gridCellHeight = Math.round((this.height + 2) / (this.latitudinalGridLines + 1));
            var gridCellWidth  = Math.round((this.width  + 2) / (this.longitudinalGridLines + 1));

            // Draw latitudinal grid lines
            for (var j = 1; j <= this.latitudinalGridLines; j++) {
                context.moveTo(0, gridCellHeight * j - 0.5);
                context.lineTo(this.width, gridCellHeight * j - 0.5);
            }

            // Draw longitudinal grid lines
            for (var i = 1; i <= this.longitudinalGridLines; i++) {
                context.moveTo(gridCellWidth * i - 0.5, 0);
                context.lineTo(gridCellWidth * i - 0.5, this.height);
            }

            context.lineWidth   = 1;
            context.strokeStyle = this.gridColor;
            context.stroke();
        },

        /**
         * Draws the points as a curve on the graph.
         */
        drawCurve: function() {
            if (this.points.length === 0)
                return;

            var context = this.context;
            var points  = this.points;

            context.beginPath();
            context.moveTo(points[0].x, points[0].y);

            for (var i = 1; i < points.length; i++) {
                context.lineTo(points[i].x, points[i].y);
            }

            context.lineWidth = 3;
            context.lineJoin = 'round';
            context.strokeStyle = this.lineColor;
            context.stroke();
        },

        /**
         * Responds to resize events and draws everything.
         */
        update: function(time, delta) {
            if (this.resizeOnNextUpdate)
                this.resize();

            if (this.graphVisible) {
                this.calculatePoints(time, delta);
                this.drawGraph(time, delta);
                this.drawCurve(time, delta);
            }
        }
    });

    return GraphView;
});


define('text!templates/graph-x-axis-buttons.html',[],function () { return '<button class="btn btn-zoom-in  zoom-in-x"><span class="fa fa-search"><span class="fa fa-plus"></span></span></button>\r\n<button class="btn btn-zoom-out zoom-out-x"><span class="fa fa-search"><span class="fa fa-minus"></span></span></button>';});


define('text!templates/graph-y-axis-buttons.html',[],function () { return '<button class="btn btn-zoom-in  zoom-in-y"><span class="fa fa-search"><span class="fa fa-plus"></span></span></button>\r\n<button class="btn btn-zoom-out zoom-out-y"><span class="fa fa-search"><span class="fa fa-minus"></span></span></button>';});

define('views/graph/moving-man',['require','jquery','common/graph/graph','nouislider','text!templates/graph-x-axis-buttons.html','text!templates/graph-y-axis-buttons.html'],function(require) {

    'use strict';

    var $ = require('jquery');

    var GraphView = require('common/graph/graph');

    require('nouislider');

    var xAxisButtonsHtml = require('text!templates/graph-x-axis-buttons.html');
    var yAxisButtonsHtml = require('text!templates/graph-y-axis-buttons.html');

    /**
     * MovingManGraphView shows the value of a given moving-man variable
     *   over time (e.g., position, velocity, or acceleration over time).
     */
    var MovingManGraphView = GraphView.extend({

        className: GraphView.prototype.className + ' moving-man-graph-view',

        events: {
            'slide .playback-time-slider' : 'changePlaybackTime',

            'click .zoom-in-x'  : 'zoomInX',
            'click .zoom-out-x' : 'zoomOutX',
            'click .zoom-in-y'  : 'zoomInY',
            'click .zoom-out-y' : 'zoomOutY'
        },

        /**
         * Internal fields
         */
        pixelRatioX: 1,
        pixelRatioY: 1,

        /**
         * Object initialization
         */
        initialize: function(options) {

            if (options.graphSeries)
                this.graphSeries = options.graphSeries;
            else
                throw 'MovingManGraphView requires a graph series object to render.';

            if (options.simulation)
                this.simulation = options.simulation;
            else
                throw 'MovingManGraphView requires a simulation model to render.';

            this.maxTimeSpan  = this.simulation.get('maxTime') || 20;
            this.maxValueSpan = Math.abs(options.y.end - options.y.start);

            this.timeSpan  = this.maxTimeSpan;
            this.valueSpan = this.maxValueSpan;

            this.hideXAxisLabelsByDefault = options.hideXAxisLabelsByDefault;

            GraphView.prototype.initialize.apply(this, [options]);

            this.listenTo(this.simulation.movingMan, 'history-cleared', function() {
                this.initPoints();
            });
            this.listenTo(this.simulation, 'change:recording', this.recordingChanged);
            this.listenTo(this.simulation, 'change:time',      this.timeChanged);

            this.on('zoom-y', this.zoomY);
        },

        /**
         * Renders html container
         */
        renderContainer: function() {
            this.$el.html(this.template(this.graphInfo));

            this.$showButton = this.$('.graph-show-button');
            this.$hideButton = this.$('.graph-hide-button');

            this.$slider = $('<div class="playback-time-slider">');
            this.$slider.noUiSlider({
                start: 0,
                range: {
                    min: 0,
                    max: 0
                }
            });
            this.$slider.find('.noUi-handle')
                .append('<div class="handle-top">')
                .append('<div class="handle-bottom">');

            if (!this.simulation.get('recording'))
                this.$slider.show();

            this.$('.graph-view-graph-wrapper').append(this.$slider);

            if (this.graphInfo.x) {
                this.$xAxisLabels = $(xAxisButtonsHtml);
                this.$('.graph-view-graph-wrapper').append(this.$xAxisLabels);
                this.$xAxisLabels = this.$xAxisLabels.add(this.$('.graph-x'));

                if (this.hideXAxisLabelsByDefault)
                    this.$xAxisLabels.hide();
            }

            if (this.graphInfo.y)
                this.$('.graph-view-graph-wrapper').append(yAxisButtonsHtml);
        },

        /**
         * Does the actual resizing of the canvas. We need to also update
         *  our cached pixel ratio.
         */
        resize: function() {
            GraphView.prototype.resize.apply(this);
            this.pixelRatioX = this.width / this.timeSpan;
            this.pixelRatioY = this.height / this.valueSpan;
            this.updateSliderOptions();
        },

        /**
         * Whenver the furthest recorded time has changed, we need to
         *   change the slider's range.  However, if this is updated
         *   while the simulation is recording, this will be called
         *   many times a second, so that needs to be avoided.
         */
        updateSliderOptions: function() {
            var max = Math.min(this.simulation.get('furthestRecordedTime'), this.timeSpan);

            this.$slider.noUiSlider({
                start: this.simulation.time,
                range: {
                    min: 0,
                    max: max
                }
            }, true); // true to rebuild

            this.$slider.width(this.pixelRatioX * max);
        },

        /**
         * Initializes points array and sets default points.  The number
         *   of points is based on the lattice width.
         */
        initPoints: function() {
            this.points = [];
        },

        /**
         * Calculates point data before drawing.
         */
        calculatePoints: function() {
            var points      = this.points;
            var height      = this.height;
            var pixelRatioX = this.pixelRatioX;
            var pixelRatioY = this.pixelRatioY;
            var graphSeries = this.graphSeries;
            var length      = graphSeries.size();

            for (var i = 0; i < length; i++) {
                if (i >= points.length)
                    this._addPoint();

                points[i].x = graphSeries.getPoint(i).time  * pixelRatioX;
                points[i].y = height / 2 - graphSeries.getPoint(i).value * pixelRatioY;
            }

            // Hide the beginning
            if (length)
                points[0].x = -1;
        },

        /**
         * Adds a blank point object to the end of the points array.
         */
        _addPoint: function() {
            this.points.push({
                x: 0,
                y: 0
            });
        },

        /**
         * Gets the time from the playback time slider and tells the
         *   simulation to seek to that time.
         */
        changePlaybackTime: function(event) {
            var time = parseFloat($(event.target).val());
            if (!isNaN(time)) {
                this.changingTime = true;
                // this.simulation.time = time;
                // this.simulation.set('time', time);
                this.simulation.setPlaybackTime(time);
                this.changingTime = false;
            }
        },

        /**
         * Updates the playback time slider according to the current
         *   time on the simulation.
         */
        timeChanged: function(model, time) {
            if (!this.simulation.get('recording') && !this.changingTime)
                this.$slider.val(time);
        },

        /**
         * Called when the sim's recording state changes and stuff
         */
        recordingChanged: function() {
            if (this.simulation.get('recording'))
                this.$slider.hide();
            else {
                this.updateSliderOptions();
                this.$slider.val(this.simulation.time);
                this.$slider.show();
            }
        },

        /**
         * Recalculates the x-axis graph info from the changed timeSpan
         *   so we can rerender.
         */
        recalculateXInfo: function() {
            if (this.graphInfo.x) {
                this.graphInfo.x.end = this.timeSpan;
                this.graphInfo.x.step = this.timeSpan / (this.longitudinalGridLines + 1);
            }
        },

        /**
         * Recalculates the y-axis graph info from the changed timeSpan
         *   so we can rerender.
         */
        recalculateYInfo: function() {
            if (this.graphInfo.y) {
                this.graphInfo.y.start = -this.valueSpan / 2;
                this.graphInfo.y.end   =  this.valueSpan / 2;
                this.graphInfo.y.step = this.valueSpan / (this.latitudinalGridLines + 1);
            }
        },

        /**
         * Sets the timeSpan, updates the graph info, and rerenders
         *   the view.
         */
        zoomX: function(timeSpan) {
            this.timeSpan = timeSpan;
            this.recalculateXInfo();
            this.render();
            this.postRender();
        },

        /**
         * Sets the valueSpan, updates the graph info, and rerenders
         *   the view.
         */
        zoomY: function(valueSpan) {
            this.valueSpan = valueSpan;
            this.recalculateYInfo();
            this.render();
            this.postRender();
        },

        /**
         * Decreases the timeSpan and triggers a zoom-x event.
         */
        zoomInX: function(event) {
            this.timeSpan -= 2;
            if (this.timeSpan < 2)
                this.timeSpan = 2;

            this.trigger('zoom-x', this.timeSpan);
        },

        /**
         * Increases the timeSpan and triggers a zoom-x event.
         */
        zoomOutX: function(event) {
            this.timeSpan += 2;
            if (this.timeSpan > this.maxTimeSpan)
                this.timeSpan = this.maxTimeSpan;

            this.trigger('zoom-x', this.timeSpan);
        },

        /**
         * Decreases the valueSpan and triggers a zoom-y event.
         */
        zoomInY: function(event) {
            var tempValueSpan = this.valueSpan - this.maxValueSpan / 8;
            if (tempValueSpan > 1) {
                this.valueSpan = tempValueSpan;
                this.trigger('zoom-y', this.valueSpan);
            }
        },

        /**
         * Increases the valueSpan and triggers a zoom-y event.
         */
        zoomOutY: function(event) {
            this.valueSpan += this.maxValueSpan / 8;
            if (this.valueSpan > this.maxValueSpan)
                this.valueSpan = this.maxValueSpan;

            this.trigger('zoom-y', this.valueSpan);
        },

        /**
         * Shows the numbers and buttons on the x-axis
         */
        showXAxisLabels: function() {
            if (this.$xAxisLabels)
                this.$xAxisLabels.show();
        },

        /**
         * Hides the numbers and buttons on the x-axis
         */
        hideXAxisLabels: function() {
            if (this.$xAxisLabels)
                this.$xAxisLabels.hide();
        }

    });

    return MovingManGraphView;
});


define('text!templates/playback-controls.html',[],function () { return '<div class="playback-controls-wrapper">\r\n    <button class="btn btn-normal clear-btn" title="Clear Recorded"><span class="fa fa-history"></span> Clear</button>\r\n\r\n    <fieldset class="playback-mode-wrapper">\r\n        <input type="radio" name="playback-mode" value="record" id="playback-mode-record" class="playback-mode" checked>\r\n        <label for="playback-mode-record">Record</label>\r\n\r\n        <input type="radio" name="playback-mode" value="playback" id="playback-mode-play" class="playback-mode">\r\n        <label for="playback-mode-play">Playback</label>\r\n    </fieldset>\r\n\r\n    <button class="playback-btn rewind-btn" title="Rewind"><span class="fa fa-fast-backward"></span></button>\r\n    <button class="playback-btn play-btn"   title="Resume"><span class="fa fa-play"></span></button>\r\n    <button class="playback-btn pause-btn"  title="Pause"><span class="fa fa-pause"></span></button>\r\n    <button class="playback-btn record-btn" title="Record"><span class="fa fa-circle"></span></button>\r\n    <button class="playback-btn step-btn"   title="Step"><span class="fa fa-step-forward"></span></button>\r\n\r\n    <div class="playback-speed-wrapper">\r\n        <label>Slow</label><div class="slider playback-speed"></div><label>Fast</label>\r\n    </div>\r\n    \r\n    <button class="btn btn-normal reset-btn" title="Reset All">Reset All</button>\r\n</div>';});


define('views/sim/charts',['require','underscore','jquery','common/app/app','models/moving-man-simulation','views/sim','views/scene','views/graph/moving-man','nouislider','text!templates/playback-controls.html','css!styles/playback-controls','css!styles/graph'],function(require) {

    'use strict';

    var _ = require('underscore');
    var $ = require('jquery');

    var AppView = require('common/app/app');

    var MovingManSimulation = require('models/moving-man-simulation');
    var MovingManSimView    = require('views/sim');
    var SceneView           = require('views/scene');
    var MovingManGraphView  = require('views/graph/moving-man');

    require('nouislider');

    // HTML
    var playbackControlsHtml = require('text!templates/playback-controls.html');

    // CSS
    require('css!styles/playback-controls');
    require('css!styles/graph');

    /**
     * Extends the functionality of the MovingManSimView to create
     *   the Charts tab.  Major differences are recording/playback
     *   and showing charts of the variables' values over time.
     */
    var ChartsSimView = MovingManSimView.extend({

        events: _.extend(MovingManSimView.prototype.events, {
            // Playback controls
            'click .play-btn'   : 'play',
            'click .record-btn' : 'play',
            'click .pause-btn'  : 'pause',
            'click .step-btn'   : 'step',
            'click .rewind-btn' : 'rewind',
            'click .reset-btn'  : 'reset',
            'click .clear-btn'  : 'clear',

            'slide .playback-speed' : 'changePlaybackSpeed',

            'change .playback-mode' : 'changePlaybackMode',

            'click .row-hide'     : 'hideRow',
            'click .row-show'     : 'showRow',
            'click .hidden-title' : 'showRow'
        }),

        initialize: function(options) {
            options = _.extend({
                title: 'Charts',
                name:  'charts'
            }, options);

            MovingManSimView.prototype.initialize.apply(this, [ options ]);

            this.listenTo(this.simulation, 'change:paused',    this.pausedChanged);
            this.listenTo(this.simulation, 'change:recording', this.recordingChanged);
        },

        /**
         * Initializes the Simulation.
         */
        initSimulation: function() {
            this.simulation = new MovingManSimulation({
                paused: true
            });
        },

        /**
         * Initializes the SceneView.
         */
        initSceneView: function() {
            this.sceneView = new SceneView({
                simulation: this.simulation,
                compact: true
            });
        },

        /**
         * Renders everything
         */
        render: function() {
            MovingManSimView.prototype.render.apply(this);

            this.renderPlaybackControls();
            this.renderGraphs();

            this.simulation.trigger('change:paused');
            this.simulation.trigger('change:recording');

            this.$el.find('.variable-controls').addClass('compact');

            return this;
        },

        /**
         * Renders the playback controls
         */
        renderPlaybackControls: function() {
            this.$('.playback-controls-placeholder').replaceWith(playbackControlsHtml);

            // Intialize controls
            this.$('.playback-speed').noUiSlider({
                start: 1,
                range: {
                    'min': [ 0.2 ],
                    '50%': [ 1 ],
                    'max': [ 4 ]
                }
            });
        },

        /**
         * Renders the graphs
         */
        renderGraphs: function() {
            var xInfo = {
                start: 0,
                end:  20,
                step:  2,
                decimalPlaces: 1,
                label: 'time (sec)',
                showNumbers: true
            };

            this.positionGraphView = new MovingManGraphView({
                title: '',
                x: xInfo,
                y: {
                    start: -10,
                    end:    10,
                    step:    5,
                    decimalPlaces: 1,
                    label:  '',
                    showNumbers: true
                },
                hideXAxisLabelsByDefault: true,
                lineColor: '#2575BA',
                latitudinalGridLines: 3,
                longitudinalGridLines: 9,
                graphSeries: this.simulation.movingMan.positionGraphSeries,
                simulation: this.simulation
            });

            this.velocityGraphView = new MovingManGraphView({
                title: '',
                x: xInfo,
                y: {
                    start: -12,
                    end:    12,
                    step:    6,
                    decimalPlaces: 1,
                    label:  '',
                    showNumbers: true
                },
                hideXAxisLabelsByDefault: true,
                lineColor: '#CD2520',
                latitudinalGridLines: 3,
                longitudinalGridLines: 9,
                graphSeries: this.simulation.movingMan.velocityGraphSeries,
                simulation: this.simulation
            });

            this.accelerationGraphView = new MovingManGraphView({
                title: '',
                x: xInfo,
                y: {
                    start: -60,
                    end:    60,
                    step:   30,
                    decimalPlaces: 1,
                    label:  '',
                    showNumbers: true
                },
                lineColor: '#349E34',
                latitudinalGridLines: 3,
                longitudinalGridLines: 9,
                graphSeries: this.simulation.movingMan.accelerationGraphSeries,
                simulation: this.simulation
            });

            this.positionGraphView.render();
            this.velocityGraphView.render();
            this.accelerationGraphView.render();

            this.$('.position-row .row-content').append(this.positionGraphView.el);
            this.$('.velocity-row .row-content').append(this.velocityGraphView.el);
            this.$('.acceleration-row .row-content').append(this.accelerationGraphView.el);

            this.positionGraphView.postRender();
            this.velocityGraphView.postRender();
            this.accelerationGraphView.postRender();

            this.graphViews = [
                this.positionGraphView,
                this.velocityGraphView,
                this.accelerationGraphView
            ];


            // Link zooming on the x-axis for all the graphs together
            _.each(this.graphViews, function(graphView) {
                this.listenTo(graphView, 'zoom-x', function(timeSpan) {
                    _.each(this.graphViews, function(view) {
                        view.zoomX(timeSpan);
                    });
                });
            }, this);
        },

        /**
         * In the Charts tab, the velocity and acceleration sliders are
         *   actually supposed to have different ranges.
         */
        initVariableSliders: function() {
            var initSlider = function($variable, options) {
                var $slider = $variable.find('.variable-slider');
                $slider.noUiSlider(options);
                $slider.Link('lower').to($variable.find('.variable-text'));
            };

            initSlider(this.$position, this.getSliderOptions());

            initSlider(this.$velocity, _.extend(this.getSliderOptions(), {
                range: {
                    min: -16,
                    max:  16
                }
            }));

            initSlider(this.$acceleration, _.extend(this.getSliderOptions(), {
                range: {
                    min: -60,
                    max:  60
                }
            }));
        },

        /**
         * Default intro view needs horizontal sliders, while the charts
         *   view has more compact variable controls with a vertical slider.
         */
        getSliderOptions: function() {
            return {
                start: 0,
                range: {
                    min: -10,
                    max:  10
                },
                orientation: 'vertical',
                direction: 'rtl'
            };
        },

        /**
         * Makes sure things like canvases are sized correctly.
         */
        postRender: function() {
            MovingManSimView.prototype.postRender.apply(this);

            this.positionGraphView.postRender();
            this.velocityGraphView.postRender();
            this.accelerationGraphView.postRender();

            this._layoutRows();
        },

        /**
         * Updates everything MovingManSimView updated as well as all the graphs.
         */
        update: function(time, delta) {
            MovingManSimView.prototype.update.apply(this, [time, delta]);

            this.positionGraphView.update(time, delta);
            this.velocityGraphView.update(time, delta);
            this.accelerationGraphView.update(time, delta);
        },

        /**
         * Pauses the simulation and rewinds it to the beginning.
         */
        rewind: function(event) {
            this.pause();
            this.simulation.rewind();
        },

        /**
         * Pauses the simulation and resets all the time and history.
         */
        clear: function(event) {
            this.pause();
            this.simulation.resetTimeAndHistory();
        },

        /**
         * Changes the playback speed on the simulation according to
         *   user input via the playback-speed slider.
         */
        changePlaybackSpeed: function(event) {
            var speed = parseFloat($(event.target).val());
            if (!isNaN(speed)) {
                this.inputLock(function(){
                    this.simulation.set('playbackSpeed', speed);
                });
            }
        },

        /**
         * Changes whether we're in playback or record mode according
         *   to user input.
         */
        changePlaybackMode: function(event) {
            var mode = $(event.target).val();
            if (mode === 'record')
                this.simulation.record();
            else
                this.simulation.stopRecording();
        },

        /**
         * The simulation changed its recording state.
         */
        recordingChanged: function() {
            if (this.simulation.get('recording')) {
                this.$el.addClass('record-mode');
                this.$('#playback-mode-record').prop('checked', true);
            }
            else {
                this.$el.removeClass('record-mode');
                this.$('#playback-mode-play').prop('checked', true);
            }
        },

        /**
         * Hides whichever variable row the user wanted to hide.
         */
        hideRow: function(event) {
            $(event.target).parents('.variable-row').addClass('collapsed');

            this._layoutRows();
        },

        /**
         * Shows whichever variable row the user wanted to show.
         */
        showRow: function(event) {
            var $row = $(event.target).parents('.variable-row');
            $row.removeClass('collapsed');
            this.rowBeingOpened = $row[0];

            this._layoutRows();

            this.lastRowOpened = $row[0];
        },

        /**
         * Applies special classes to rows after one was hidden/shown.
         */
        _layoutRows: function() {
            var shortScreen = AppView.windowIsShort();

            // Get the total height we have to work with
            var height = shortScreen ? 340 : 480;

            // Clear previously set heights
            this.$('.variable-row').each(function(){
                $(this).css('height', '');
            });

            // Get lists of each kind of row
            var $visibleRows   = this.$('.variable-row').not('.collapsed');
            var $collapsedRows = this.$('.variable-row.collapsed');

            // If we are dealingn with a short screen, we need to constrain it
            //   to only let two be open at a time because we're tight on space
            if (shortScreen && $visibleRows.length > 2) {
                var $rowToClose;
                var rowBeingOpened = this.rowBeingOpened;
                var lastRowOpened  = this.lastRowOpened;
                $visibleRows.each(function() {
                    if (this !== rowBeingOpened && this !== lastRowOpened)
                        $rowToClose = $(this);
                });

                $rowToClose.addClass('collapsed');

                $visibleRows   = this.$('.variable-row').not('.collapsed');
                $collapsedRows = this.$('.variable-row.collapsed');
            }

            // Make sure the last graph shows the x-axis labels below it
            var lastOpenIndex = $visibleRows.last().index();
            for (var i = 0; i < this.graphViews.length; i++) {
                if (i === lastOpenIndex)
                    this.graphViews[i].showXAxisLabels();
                else
                    this.graphViews[i].hideXAxisLabels();
            }

            // Calculate the height of each visible row
            var totalCollapsedHeight = $collapsedRows.length * $collapsedRows.outerHeight();
            var visibleRowHeight = (height - totalCollapsedHeight) / $visibleRows.length;

            // Apply that height to each of the visible rows
            $visibleRows.each(function(){
                $(this).innerHeight(visibleRowHeight);
            });

            // Resize the graphs
            this.positionGraphView.resize();
            this.velocityGraphView.resize();
            this.accelerationGraphView.resize();
        }

    });

    return ChartsSimView;
});




define('text!templates/universal-controls.html',[],function () { return '<div class="sound-btn-wrapper">\r\n    <button class="sound-btn sound-btn-mute" title="Mute effect volume (click to raise)"><span class="fa fa-volume-off"></span></button>\r\n    <button class="sound-btn sound-btn-low"  title="Low effect volume (click to raise)"><span class="fa fa-volume-down"></span></button>\r\n    <button class="sound-btn sound-btn-high" title="High effect volume (click to mute)"><span class="fa fa-volume-up"></span></button>\r\n</div>';});

define('views/app',['require','underscore','common/app/app','views/sim/intro','views/sim/charts','css!styles/font-awesome','css!styles/app','text!templates/universal-controls.html'],function(require) {

    'use strict';

    var _ = require('underscore');

    var AppView = require('common/app/app');

    var IntroSimView  = require('views/sim/intro');
    var ChartsSimView = require('views/sim/charts');

    require('css!styles/font-awesome');
    require('css!styles/app');

    var universalControlsHtml = require('text!templates/universal-controls.html');

    var MovingManAppView = AppView.extend({

        simViewConstructors: [
            IntroSimView,
            ChartsSimView
        ],

        events: _.extend({}, AppView.prototype.events, {
            'click .sound-btn' : 'changeVolume'
        }),

        /**
         * Override render function to add universal controls
         */
        render: function() {
            AppView.prototype.render.apply(this);

            this.$el.append(universalControlsHtml);
        },

        /**
         * Steps between the different discrete volume values and updates
         *   the button's icon.
         */
        changeVolume: function(event) {
            var $btn = $(event.target).closest('.sound-btn');

            $btn.hide();

            if ($btn.hasClass('sound-btn-mute')) {
                this.$('.sound-btn-low').show();
                _.each(this.simViews, function(simView) {
                    simView.sceneView.movingManView.lowVolume();
                });
            }
            else if ($btn.hasClass('sound-btn-low')) {
                this.$('.sound-btn-high').show();
                _.each(this.simViews, function(simView) {
                    simView.sceneView.movingManView.highVolume();
                });
            }
            else if ($btn.hasClass('sound-btn-high')) {
                this.$('.sound-btn-mute').show();
                _.each(this.simViews, function(simView) {
                    simView.sceneView.movingManView.muteVolume();
                });
            }
        },

    });

    return MovingManAppView;
});

(function () {
    'use strict';

    // Load the config
    require(['config'], function () {
        require(['jquery', 'views/app'], function($, MovingManAppView) {

            $(function(){
                var appView = new MovingManAppView();

                // Append to body
                $('body').append(appView.el);

                // Render main app view
                appView.load();
            });

        });
    });

})();

define('main', function(){});

